import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { execFileSync } from "node:child_process";
import { describe, expect, it } from "vitest";

/**
 * Guards the documentation: a paragraph must not appear twice in the same document (a bad scripted edit once
 * duplicated parts of CLAUDE.md), and file paths named in backticks must exist.
 */
const root = join(__dirname, "..");
const documents = execFileSync("git", ["ls-files", "*.md"], { cwd: root, encoding: "utf8" })
  .split("\n")
  .filter(Boolean)
  // AGENTS.md is generated by Next.js
  .filter((file) => file !== "AGENTS.md");

describe("documentation", () => {
  it("has no paragraph that appears twice in one document", () => {
    const duplicates: string[] = [];
    for (const file of documents) {
      const seen = new Set<string>();
      for (const line of readFileSync(join(root, file), "utf8").split("\n")) {
        const text = line.trim();
        if (text.length < 80) continue;
        if (seen.has(text)) duplicates.push(`${file}: ${text.slice(0, 70)}...`);
        seen.add(text);
      }
    }
    expect(duplicates).toEqual([]);
  });

  it("only names files that exist", () => {
    const missing: string[] = [];
    // Paths in a repository folder, with a file extension; placeholders and globs are skipped.
    const pathPattern = /`((?:src|scripts|tests|docs|messages|supabase)\/[A-Za-z0-9_./-]+\.[a-z]{1,5})`/g;
    for (const file of documents) {
      for (const match of readFileSync(join(root, file), "utf8").matchAll(pathPattern)) {
        if (!existsSync(join(root, match[1]))) missing.push(`${file}: ${match[1]}`);
      }
    }
    expect([...new Set(missing)]).toEqual([]);
  });
});
